"""Writes docs/example.tex: the timed speed-governor chain, worked by DELEGATE. Every readable form below is
asserted equivalent (Z3) to what scripts/delegate.py computes before it is typeset."""
import sys, io, contextlib
sys.path.insert(0, "scripts")
from delegate import *
from fractions import Fraction as Fr
def quiet(f, *a):
    with contextlib.redirect_stdout(io.StringIO()): return f(*a)
def eq(a, b): return valid(a == b)
H = 2
SG = Arch({"Perception": (["o"], ["e"]), "Controller": (["e"], ["u"]), "Actuator": (["u"], ["v"])}, env=["o"], H=H)
o = lambda t: V("o", t); e = lambda t: V("e", t); u = lambda t: V("u", t); v = lambda t: V("v", t)
AP = Alw(0, 2, lambda t: And(o(t) >= 0, o(t) <= 5))(0)
GP = And(Alw(0, 2, lambda t: And(v(t) >= 0, v(t) <= 2))(0),
         Alw(0, 1, lambda t: Implies(o(t) <= 1, Ev(0, 1, lambda s: v(s) <= Fr(1, 4))(t)))(0),
         Alw(0, 1, lambda t: Implies(o(t) >= 3, Ev(0, 1, lambda s: v(s) >= 1)(t)))(0))
R = quiet(delegate, SG, AP, GP, "sg")
assert R is not None and valid(R["phi"])
# seed
assert eq(R["seed"]["Perception"], And(e(0) == o(0), e(1) == o(1), e(2) == o(2)))
assert eq(R["seed"]["Controller"], And(u(0) == e(0), u(1) == e(1), u(2) == e(2)))
sa = R["seed"]["Actuator"]; eqs = {}
for c in sa.children():
    a, b = c.children()
    if is_const(a) and a.decl().kind() == Z3_OP_UNINTERPRETED: eqs[str(a)] = b
    else: eqs[str(b)] = a
ubox = And(*[And(u(t) >= 0, u(t) <= 5) for t in range(3)])
v0 = eqs["v_0"]; v1 = simplify(substitute(eqs["v_1"], (v(0), v0))); v2 = simplify(substitute(substitute(eqs["v_2"], (v(0), v0)), (v(1), v1)))
assert eq(v0, RealVal(1)); assert valid(Implies(ubox, v1 == RealVal(Fr(1, 8)))); assert valid(Implies(ubox, v2 == If(u(1) >= 3, RealVal(1), RealVal(Fr(1, 8)))))
# sweep
AP_, GPer = R["sweep"]["Perception"]; AC, GC = R["sweep"]["Controller"]; AA, GA = R["sweep"]["Actuator"]
ebox = And(*[And(e(t) >= 0, e(t) <= 5) for t in range(3)]); vbox = And(*[And(v(t) >= 0, v(t) <= 2) for t in range(3)])
assert eq(AP_, AP) and eq(GPer, Implies(And(AP, o(1) >= 3), And(ebox, e(1) >= 3)))
assert eq(AC, BoolVal(True)) and eq(GC, Implies(And(ebox, e(1) >= 3), And(ubox, u(1) >= 3)))
assert eq(AA, BoolVal(True)) and eq(GA, And(vbox, Or(v(0) >= 1, v(1) >= 1), Or(v(0) <= Fr(1, 4), v(1) <= Fr(1, 4)),
                                            Or(v(1) <= Fr(1, 4), v(2) <= Fr(1, 4)), Implies(And(ubox, u(1) >= 3), Or(v(1) >= 1, v(2) >= 1))))
# unrealizable variant
GPu = And(Alw(0, 2, lambda t: And(v(t) >= 0, v(t) <= 2))(0), Alw(0, 2, lambda t: Implies(o(t) <= 1, v(t) <= Fr(1, 4)))(0),
          Alw(0, 1, lambda t: Implies(o(t) >= 3, Ev(1, 1, lambda s: v(s) >= 1)(t)))(0))
assert quiet(delegate, SG, AP, GPu, "sgu") is None
print("all forms verified")
tex = r"""\documentclass[10pt]{article}\usepackage[margin=0.75in]{geometry}\usepackage{amsmath,amssymb,booktabs}
\setlength{\parskip}{3pt}\setlength{\parindent}{0pt}
\makeatletter\renewcommand\section{\@startsection{section}{1}{\z@}{7pt}{3pt}{\normalfont\bfseries}}\makeatother
\begin{document}
\begin{center}\textbf{A timed example: the speed governor chain}\\ 19 October 2026. Companion to \emph{complete.pdf}. Generated by \texttt{scripts/example\_report.py}; every formula shown was checked by Z3 to be equivalent to what \texttt{scripts/delegate.py} computes. The instance is part of the one command \texttt{.venv/bin/python scripts/delegate.py}.\end{center}

\section{The instance}
Three components in a chain. \textbf{Perception} reads the environment variable $o$ (distance to an obstacle) and writes an estimate $e$. \textbf{Controller} reads $e$ and writes a command $u$. \textbf{Actuator} reads $u$ and writes the speed $v$. Horizon $H=2$, so each variable has values at times $0,1,2$; all delays are $0$. The query mentions only $o$ and $v$; $e$ and $u$ are internal.
\[
A_P=\square_{[0,2]}\,(0\le o\le5),\qquad
G_P=\square_{[0,2]}\,(0\le v\le2)\ \wedge\ \square_{[0,1]}\big(o\le1\to\Diamond_{[0,1]}\,v\le\tfrac14\big)\ \wedge\ \square_{[0,1]}\big(o\ge3\to\Diamond_{[0,1]}\,v\ge1\big).
\]
In words: the speed stays in $[0,2]$; whenever the obstacle is close ($o\le1$) the speed drops to at most $\tfrac14$ within one step; whenever the way is clear ($o\ge3$) the speed reaches at least $1$ within one step. Unrolled, the two response conjuncts become, for $t=0,1$: $(o(t)\le1\to v(t)\le\tfrac14\vee v(t{+}1)\le\tfrac14)$ and $(o(t)\ge3\to v(t)\ge1\vee v(t{+}1)\ge1)$.

\section{What the procedure does}
\textbf{Steps 1--3.} All three components can influence $v$, so all are relevant. The only topological ordering is Perception, Controller, Actuator. It is nested: Perception sees $o$, which Controller does not, and has the one edge variable $e$ to carry it; Controller sees $e$, which Actuator does not, and has $u$; neither $e$ nor $u$ occurs in the query; only Perception reads the environment. Forwarding formulas: $F_1=\bigwedge_t e(t)=o(t)$ and $F_2=\bigwedge_t u(t)=e(t)$. The only terminal output is $v$, so the sentence is
\[
\Phi=\forall o(0)\,\exists v(0)\ \forall o(1)\,\exists v(1)\ \forall o(2)\,\exists v(2)\ \ (A_P\to G_P),
\]
read: for every obstacle distance at time 0 there is a speed at time 0, such that for every distance at time 1 there is a speed at time 1, and so on, making the query true.

\textbf{Steps 4--5.} Quantifier elimination decides $\Phi$: \textbf{true}. \textbf{Step 6--7.} The witnesses, read back through the forwarding ($o$ arrives at the Actuator as $u$), give the seed delegation:
\begin{center}\begin{tabular}{@{}lll@{}}\toprule component & assumption & guarantee (seed)\\\midrule
Perception & true & $e(t)=o(t)$ for $t=0,1,2$\\
Controller & true & $u(t)=e(t)$ for $t=0,1,2$\\
Actuator & true & $v(0)=1,\quad v(1)=\tfrac18,\quad v(2)=\begin{cases}1&u(1)\ge3\\ \tfrac18&\text{otherwise}\end{cases}$ (on $0\le u(t)\le5$)\\\bottomrule\end{tabular}\end{center}
The witness is lazy by construction: it starts fast ($v(0)=1$ answers a clear road at time 0 at once), goes slow at time 1 ($\tfrac18$ answers a close obstacle at time 0 or 1), and at time 2 goes fast again exactly when the command says the road was clear at time 1. Z3 confirms (V1), (V2), and that each component is receptive and causal.

\textbf{Steps 8--9 (sweep).} Each contract is replaced, in order, by the weakest one that still works with the others, then the assumptions are recomputed. The result, written out (equivalences checked by Z3):
\begin{center}\begin{tabular}{@{}lll@{}}\toprule component & assumption & guarantee (final)\\\midrule
Perception & $A_P$ & $\big(A_P\wedge o(1)\ge3\big)\ \to\ \big(\textstyle\bigwedge_t 0\le e(t)\le5\ \wedge\ e(1)\ge3\big)$\\[2pt]
Controller & true & $\big(\textstyle\bigwedge_t 0\le e(t)\le5\wedge e(1)\ge3\big)\ \to\ \big(\textstyle\bigwedge_t 0\le u(t)\le5\wedge u(1)\ge3\big)$\\[2pt]
Actuator & true & $\textstyle\bigwedge_t 0\le v(t)\le2\ \wedge\ (v(0)\ge1\vee v(1)\ge1)\ \wedge\ (v(0)\le\tfrac14\vee v(1)\le\tfrac14)\ \wedge\ (v(1)\le\tfrac14\vee v(2)\le\tfrac14)$\\
 & & $\wedge\ \big(\textstyle\bigwedge_t 0\le u(t)\le5\wedge u(1)\ge3\ \to\ v(1)\ge1\vee v(2)\ge1\big)$\\\bottomrule\end{tabular}\end{center}
(V1), (V2), receptiveness and causality hold after the sweep (Z3).

\section{Reading the result}
The final contracts say precisely what each component must preserve, and nothing more.
\begin{itemize}
\item \textbf{Perception} must preserve exactly one feature: if the road is clear at time 1 ($o(1)\ge3$), the estimate at time 1 must also say so ($e(1)\ge3$) and stay in range. Nothing else about $o$ has to reach the chain. The reason is in the Actuator's final contract: a close obstacle is handled without information, by being slow at time 1 and again at time 1 or 2, and a clear road at time 0 by being fast at time 0 or 1; the only case that needs information from the environment is the clear road at time 1, which must be answered at time 1 or 2 and cannot be answered blindly without breaking the slow-down obligation.
\item \textbf{Controller} must pass that one feature on: estimate in range and $e(1)\ge3$ implies command in range and $u(1)\ge3$.
\item \textbf{Actuator} must keep the speed in range, be fast at time 0 or 1, be slow at time 0 or 1 and at time 1 or 2, and, whenever the command certifies a clear road at time 1, be fast at time 1 or 2. Its final contract is weaker than the seed strategy: for instance $v(0)=\tfrac18$, $v(1)=1$ is also allowed.
\end{itemize}
The exact copies $e=o$, $u=e$ of the seed are gone; what remains on the edges is the one implication the query actually needs. This is the sweep doing its job: the forwarding seed only serves to find a solution, and quotient plus projection then remove everything the query does not require.

\section{A refutation}
Change the query to demand an immediate slow-down and a fast response exactly one step later:
$G_P'=\square_{[0,2]}(0\le v\le2)\wedge\square_{[0,2]}(o\le1\to v\le\tfrac14)\wedge\square_{[0,1]}(o\ge3\to\Diamond_{[1,1]}\,v\ge1)$. The sentence $\Phi$ is \textbf{false}: the environment can present a clear road at time 0 and a close obstacle at time 1, which demands $v(1)\ge1$ and $v(1)\le\tfrac14$. The procedure reports that no acceptable delegation exists, by the necessity theorem, before any contract is written.
\end{document}
"""
open("docs/example.tex", "w").write(tex); print("example.tex written")
